// Build-time Easton's Bible Dictionary data (generated by scripts/generate-bible-dictionary.mjs).
import entriesJson from "./entries.json";
import placeEntriesJson from "./place-entries.json";
import manifestJson from "./manifest.json";

/**
 * Inline segment: plain text, [text, flags] (1 = italic), [text, flags, from, to?]
 * (scripture link, verse codes) or [text, flags, slug] (link to another entry).
 */
export type DictSeg = string | [string, number] | [string, number, number] | [string, number, number, number] | [string, number, string];
/** p = paragraph, h = heading between two articles that share a headword. */
export type DictPara = ["p" | "h", ...DictSeg[]];
export type DictEntry = { slug: string; title: string; paras: DictPara[]; places?: string[] };

export const dictEntries = entriesJson as DictEntry[];
export const dictEntryBySlug = new Map(dictEntries.map(e => [e.slug, e]));
/** Bible map place slug -> dictionary entry slug. */
export const dictEntryForPlace = placeEntriesJson as Record<string, string>;
export const dictManifest = manifestJson;
